@startuml

class Course {
  + name : string
}

class Edition {
}

class Lesson {
  + date : date
  + startTime : time
  + duration : string
}

class Room {
  + name : string
}

abstract class Teacher {
  + name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {}

class ExternalAuditor {}

Course "1" -- "*" Edition
Edition "1" -- "*" Lesson
Lesson "*" -- "1" Room
Lesson "*" -- "1..*" Teacher
Course "0..*" -- "1" InternalTeacher : responsible
Course "0..*" -- "*" Teacher : preallocated

Edition "1" -- "*" MasterStudent
Edition "1" -- "*" ExternalAuditor

@enduml

